"use strict";
/* z4: MANDATORY phone + Make mailhook BCC installer.
 *  - phone now required on the booking form (lenient, >=9 digits), Hungarian error
 *  - phone shown in the host new-booking email (tap-to-call), under the name
 *  - NEW-booking host notice BCC-copied to the Make mailhook (nothing else)
 * Replaces 6 code files (backups .bak4), surgically sets clients.json
 * host_notify_copy for foglalas-okosan (live host_email + keys preserved),
 * syntax-checks, restarts, prints health. UTM tracking untouched.
 * Run:  node z4.js   (optional: node z4.js /opt/foglalas-engine norestart) */
const fs = require("fs"), path = require("path"), cp = require("child_process");
const APP = process.argv[2] || "/opt/foglalas-engine";
const FILES = {"src/booking.js":"","src/engine.js":"","src/senders.js":"","src/emailhtml.js":"","src/templates.js":"","src/bookingpages.js":""};

try {
  for (const [rel, b64] of Object.entries(FILES)) {
    const p = path.join(APP, rel);
    if (!fs.existsSync(p)) { console.error("MISSING " + p); process.exit(1); }
    fs.copyFileSync(p, p + ".bak4");
    fs.writeFileSync(p, Buffer.from(b64, "base64"));
    cp.execSync("node --check " + p);
    console.log("updated " + rel);
  }
  // --- surgical clients.json patch: add host_notify_copy ONLY (live keys/host_email untouched) ---
  const CJ = path.join(APP, "data/clients.json");
  if (fs.existsSync(CJ)) {
    fs.copyFileSync(CJ, CJ + ".bak4");
    const cj = JSON.parse(fs.readFileSync(CJ, "utf8"));
    if (cj["foglalas-okosan"]) {
      cj["foglalas-okosan"].host_notify_copy = "zsvuvjvdlr06o8u33lubr66584pn1czx@hook.eu1.make.com";
      fs.writeFileSync(CJ, JSON.stringify(cj, null, 2));
      console.log("clients.json: host_notify_copy set for foglalas-okosan (host_email + keys preserved)");
    } else { console.error("WARN foglalas-okosan missing in clients.json"); }
  } else { console.error("WARN clients.json not found at " + CJ); }
  console.log("syntax ok");
  if (process.argv[3] !== "norestart") {
    cp.execSync("systemctl restart foglalas-engine");
    cp.execSync("sleep 3");
    const out = cp.execSync("curl -s http://localhost:3000/health").toString();
    console.log("health: " + out);
    console.log(out.includes('"ok":true') ? "Z4-DEPLOY-DONE" : "HEALTH-NOT-OK check journalctl -u foglalas-engine");
  } else console.log("norestart done");
} catch (e) { console.error("FAILED: " + e.message); process.exit(1); }
